        },
        body: JSON.stringify({ text: data.text, model_id: "eleven_turbo_v2_5" }),
      },
    );
    if (!r.ok) throw new Error(`TTS failed: ${r.status}`);
    const buf = await r.arrayBuffer();
    return { audio: Buffer.from(buf).toString("base64") };
  });
```

